// ============================================================================
//  tb_frameseq.v -- twn_frameseq with the real twn_desctab loaded from
//  tb_desctab_words.vh (generated by tools/gen_desctab.py).
//
//  twn_blockseq and twn_wfetch are modelled as counters with programmable
//  durations. Per frame it checks: every block computes once (count and mask),
//  the number of fetches equals the block count (block 0 up front, then one per
//  successor), `done` fires once, and compute and fetch overlap in at least one
//  cycle. Block order is printed as "ORDER:" lines but is not counted as an
//  error. Four (compute, fetch) duration pairs are run, including fetch longer
//  than compute. Pass line: "=== tb_frameseq: ... ALL PASS ===".
// ============================================================================
`timescale 1ns/1ps
`default_nettype none

module tb_frameseq;
    `include "tb_desctab_words.vh"

    reg clk = 1'b0, rst = 1'b1;
    always #2 clk = ~clk;

    // ---- the descriptor table, loaded directly ----
    reg         d_wr_en;
    reg  [12:0] d_wr_addr;
    reg  [31:0] d_wr_data;
    wire        desc_ready, descf_ready;
    wire [4:0]  blk, blk_f;
    wire [9:0]  c_in, c_mid, c_out;
    wire [15:0] n_tern;
    wire [13:0] fb_tern;

    twn_desctab DT (
        .clk(clk), .rstn(~rst),
        .wr_en(d_wr_en), .wr_addr(d_wr_addr), .wr_data(d_wr_data),
        .n_blocks(DT_NBLK[4:0]),
        .check(1'b0), .check_busy(), .check_done(), .valid(), .err_code(),
        .err_block(),
        .blk(blk), .desc_ready(desc_ready),
        .c_in(c_in), .c_mid(c_mid), .c_out(c_out),
        .h_in(), .w_in(), .s_dw(), .pack_e(), .pack_p(),
        .in_slot(), .out_slot(), .res_slot(), .has_res(),
        .row_bytes_in(), .row_bytes_out(),
        .mb_tern(), .mb_dw(), .mb_rqa(), .mb_rqd(),
        .blk_f(blk_f), .descf_ready(descf_ready),
        .off_tern(), .off_dw(), .off_rqa(), .off_rqd(),
        .n_tern(n_tern), .n_dw(), .n_rqa(), .n_rqd(),
        .fb_tern(fb_tern), .fb_dw(), .fb_rqa(), .fb_rqd());

    // ---- the sequencer ----
    reg  ap_start;
    wire busy, done, blk_start, wf_start;
    reg  blk_busy, blk_done, wf_busy, wf_done;

    twn_frameseq FS (
        .clk(clk), .rst(rst),
        .ap_start(ap_start), .n_blocks(DT_NBLK[4:0]), .busy(busy), .done(done),
        .blk(blk), .blk_f(blk_f),
        .desc_ready(desc_ready), .descf_ready(descf_ready),
        .blk_start(blk_start), .blk_busy(blk_busy), .blk_done(blk_done),
        .wf_start(wf_start), .wf_busy(wf_busy), .wf_done(wf_done));

    // ---- modelled compute and fetch ----
    integer c_len, f_len, c_cnt, f_cnt;
    integer overlap_cycles, n_compute, n_fetch, n_done;
    reg [31:0] ran;                                   // which blocks computed
    integer last_blk;

    always @(posedge clk) begin
        if (rst) begin
            blk_busy <= 1'b0; blk_done <= 1'b0; c_cnt <= 0;
            wf_busy  <= 1'b0; wf_done  <= 1'b0; f_cnt <= 0;
        end else begin
            blk_done <= 1'b0; wf_done <= 1'b0;
            if (blk_start) begin blk_busy <= 1'b1; c_cnt <= c_len; end
            else if (blk_busy) begin
                if (c_cnt <= 1) begin blk_busy <= 1'b0; blk_done <= 1'b1; end
                else c_cnt <= c_cnt - 1;
            end
            if (wf_start) begin wf_busy <= 1'b1; f_cnt <= f_len; end
            else if (wf_busy) begin
                if (f_cnt <= 1) begin wf_busy <= 1'b0; wf_done <= 1'b1; end
                else f_cnt <= f_cnt - 1;
            end
        end
    end

    // ---- observation ----
    always @(posedge clk) if (!rst) begin
        if (blk_start) begin
            n_compute = n_compute + 1;
            ran[blk]  = 1'b1;
            if (blk !== last_blk[4:0] + 5'd1 && n_compute > 1)
                $display("  ORDER: block %0d ran after %0d", blk, last_blk);
            last_blk = blk;
        end
        if (wf_start) n_fetch = n_fetch + 1;
        if (blk_busy && wf_busy) overlap_cycles = overlap_cycles + 1;
        if (done) n_done = n_done + 1;
    end

    integer errors = 0, checks = 0, b, w, ci;
    reg [31:0] want_ran;

    task load_table;
        begin
            for (b = 0; b < DT_NBLK; b = b + 1)
                for (w = 0; w < 16; w = w + 1) begin
                    @(negedge clk);
                    d_wr_en   = 1'b1;
                    d_wr_addr = b * 16 + w;
                    d_wr_data = DT_WORDS[(b * 16 + w) * 32 +: 32];
                end
            @(negedge clk); d_wr_en = 1'b0;
        end
    endtask

    task one_frame;
        input integer cl;
        input integer fl;
        input [8*16-1:0] name;
        integer guard;
        begin
            c_len = cl; f_len = fl;
            n_compute = 0; n_fetch = 0; n_done = 0;
            overlap_cycles = 0; ran = 32'd0; last_blk = -1;
            @(negedge clk); ap_start = 1'b1;
            @(negedge clk); ap_start = 1'b0;
            guard = 0;
            while (!done && guard < 400000) begin @(negedge clk); guard = guard + 1; end
            @(negedge clk);

            checks = checks + 5;
            want_ran = (32'd1 << DT_NBLK) - 32'd1;
            if (n_compute !== DT_NBLK) begin
                errors = errors + 1;
                $display("  %0s: %0d blocks computed, want %0d", name, n_compute, DT_NBLK);
            end
            if (ran !== want_ran) begin
                errors = errors + 1;
                $display("  %0s: ran mask %h, want %h", name, ran, want_ran);
            end
            // one prefetch of block 0 plus one per block that has a successor
            if (n_fetch !== DT_NBLK) begin
                errors = errors + 1;
                $display("  %0s: %0d fetches, want %0d (block 0 up front, then one per successor)",
                         name, n_fetch, DT_NBLK);
            end
            if (n_done !== 1) begin
                errors = errors + 1;
                $display("  %0s: done fired %0d times", name, n_done);
            end
            // overlap of compute and fetch
            if (overlap_cycles == 0) begin
                errors = errors + 1;
                $display("  %0s: compute and fetch NEVER overlapped -- the fetch is not hidden",
                         name);
            end
            $display("  %0s: %0d blocks, %0d fetches, %0d overlapped cycles",
                     name, n_compute, n_fetch, overlap_cycles);
        end
    endtask

    initial begin
        ap_start = 1'b0; d_wr_en = 1'b0;
        n_compute = 0; n_fetch = 0; n_done = 0; overlap_cycles = 0;
        ran = 32'd0; last_blk = -1; c_len = 20; f_len = 10;
        repeat (8) @(negedge clk);
        rst = 1'b0;
        @(negedge clk);
        load_table;

        one_frame(40, 10, "compute longer");
        one_frame(10, 40, "fetch longer");     // a sequencer that waits on only
                                               // one of the two fails here
        one_frame(15, 15, "equal");
        one_frame( 3,  3, "very short");

        $display("=== tb_frameseq: %0d blocks, %0d assertions, %0d errors, %s ===",
                 DT_NBLK, checks, errors,
                 (errors == 0 && checks > 0) ? "ALL PASS" : "FAIL");
        $finish;
    end

    initial begin
        #50_000_000;
        $display("=== tb_frameseq: TIMEOUT, %0d errors ===", errors);
        $finish;
    end
endmodule
`default_nettype wire
